{"command":"cat > /tmp/h/drive.py <<'EOF'
# drive the program: type the lesson text automatically
import os, pty, sys, time, select, struct, fcntl, termios, signal
sys.path.insert(0,'/tmp/h'); from vt import Screen
class Prog:
    def __init__(s,args,W=80,H=24):
        s.pid, s.fd = pty.fork()
        if s.pid==0:
            os.execv(args[0], args)
        fcntl.ioctl(s.fd, termios.TIOCSWINSZ, struct.pack('HHHH',H,W,0,0))
        s.sc=Screen(W,H)
    def pump(s,quiet=0.05,timeout=5,until=None):
        t0=time.time(); last=time.time()
        while True:
            r,_,_=select.select([s.fd],[],[],0.005)
            if r:
                try: d=os.read(s.fd,65536)
                except OSError: return
                if not d: return
                s.sc.feed(d); last=time.time()
            if until is None:
                if time.time()-last>quiet: return
            else:
                if until(s.sc) and time.time()-last>quiet: return
            if time.time()-t0>timeout: return
    def send(s,b):
        if isinstance(b,str): b=b.encode()
        os.write(s.fd,b)
    def line(s,y): return ''.join(s.sc.g[y])
    def lesson_text(s): return s.sc.bold_run(6)
    def kill(s):
        os.kill(s.pid,signal.SIGKILL); os.waitpid(s.pid,0); os.close(s.fd)
EOF
