for i in range(6):
    t=p.lesson_text(); print(p.line(3).strip(), repr(t))
    # fail on purpose on odd lessons by waiting
    if i%2==0:
        p.send(t[0]); time.sleep(2.5); p.send(t[1:])
    else:
        p.send(t)
    p.pump(until=lambda sc: ('Lesson #%d'%(i+2)) in sc.text())
    print("  ", p.line(16).strip(), p.line(17).strip())
p.kill()
EOF
