{"command":"cd /workspace && cat > src/game.rs <<'EOF'
//! Lesson generation and per-lesson typing statistics.

use rand::seq::SliceRandom;
use std::time::Instant;

/// Builds the text of a new lesson.
///
/// `combi` entries are drawn (with replacement) from `ngrams`, the resulting
/// sequence is then repeated `rep` times. Every entry is followed by a space,
/// so the lesson text always ends with a trailing space.
pub fn generate_lesson(ngrams: &[String], combi: usize, rep: usize) -> String {
    let mut rng = rand::thread_rng();
    let mut picks: Vec<&str> = Vec::with_capacity(combi);

    // draw the entries for this lesson; an empty pool cannot produce a lesson
    // and is treated as a fatal error.
