//! Keyboard layouts used for display and for layout emulation.

/// A keyboard layout described by its three letter rows (top, home, bottom).
#[derive(Debug, Clone, Copy)]
pub struct KeyboardLayout {
    pub rows: [&'static str; 3],
}

pub const QWERTY: KeyboardLayout = KeyboardLayout {
    rows: ["qwertyuiop[]", "asdfghjkl;'", "zxcvbnm,./"],
};

pub const QWERTZ: KeyboardLayout = KeyboardLayout {
    rows: ["qwertzuiopü+", "asdfghjklöä", "yxcvbnm,.-"],
};

pub const AZERTY: KeyboardLayout = KeyboardLayout {
    rows: ["azertyuiop^$", "qsdfghjklmù", "wxcvbn,;:!"],
};

pub const DVORAK: KeyboardLayout = KeyboardLayout {
    rows: ["',.pyfgcrl/=", "aoeuidhtns-", ";qjkxbmwvz"],
};

pub const COLEMAK: KeyboardLayout = KeyboardLayout {
    rows: ["qwfpgjluy;[]", "arstdhneio'", "zxcvbkm,./"],
};

pub const COLEMAK_DH: KeyboardLayout = KeyboardLayout {
    rows: ["qwfpbjluy;[]", "arstgmneio'", "zxcdvkh,./"],
};

impl KeyboardLayout {
    /// Looks up a layout by name. Unknown names fall back to qwerty.
    pub fn from_name(name: &str) -> KeyboardLayout {
        match name {
            "qwerty" => QWERTY,
            "qwertz" => QWERTZ,
            "azerty" => AZERTY,
            "dvorak" => DVORAK,
            "colemak" => COLEMAK,
            "colemakdh" => COLEMAK_DH,
            _ => QWERTY,
        }
    }

    /// All keys of the layout, row by row.
    pub fn keys(&self) -> Vec<char> {
        self.rows.iter().flat_map(|r| r.chars()).collect()
    }
}

/// Translates key presses made on one layout into the characters of another.
pub struct Emulator {
    from: Vec<char>,
    to: Vec<char>,
}

impl Emulator {
    pub fn new(input: KeyboardLayout, output: KeyboardLayout) -> Self {
        Emulator {
            from: input.keys(),
            to: output.keys(),
        }
    }

    pub fn translate(&self, c: char) -> char {
        match self.from.iter().position(|&k| k == c) {
            Some(i) => self.to.get(i).copied().unwrap_or(c),
            None => c,
        }
    }
}

fn key_row(keys: &[String]) -> String {
    let mut s = String::from("│");
    for k in keys {
        s.push(' ');
        s.push_str(k);
        s.push_str(" │");
    }
    s
}

/// Renders the keyboard as seven lines of box drawing characters.
pub fn keyboard_lines(layout: &KeyboardLayout, ortho: bool) -> Vec<String> {
    let rows: Vec<Vec<String>> = layout
        .rows
        .iter()
        .map(|r| r.chars().map(|c| c.to_string()).collect())
        .collect();

    if ortho {
        let width = rows.iter().map(|r| r.len()).max().unwrap_or(0);
        let padded: Vec<Vec<String>> = rows
            .iter()
            .map(|r| {
                let mut r = r.clone();
                while r.len() < width {
                    r.push("△".to_string());
                }
                r
            })
            .collect();
        let line = |l: &str, m: &str, r: &str| -> String {
            let mut s = String::from(l);
            for i in 0..width {
                s.push_str("───");
                s.push_str(if i + 1 == width { r } else { m });
            }
            s
        };
        vec![
            line("┌", "┬", "┐"),
            key_row(&padded[0]),
            line("├", "┼", "┤"),
            key_row(&padded[1]),
            line("├", "┼", "┤"),
            key_row(&padded[2]),
            line("└", "┴", "┘"),
        ]
    } else {
        let top = |n: usize| -> String {
            let mut s = String::from("┌");
            for i in 0..n {
                s.push_str("───");
                s.push_str(if i + 1 == n { "┐" } else { "┬" });
            }
            s
        };
        // separator between a row and the (shorter, shifted) row below it
        let between = |indent: usize, below: usize| -> String {
            let mut s = " ".repeat(indent);
            s.push('└');
            for i in 0..below {
                s.push_str("┬──");
                s.push_str(if i + 1 == below { "┘" } else { "┴" });
            }
            s
        };
        let bottom = |indent: usize, n: usize| -> String {
            let mut s = " ".repeat(indent);
            s.push('└');
            for i in 0..n {
                s.push_str("───");
                s.push_str(if i + 1 == n { "┘" } else { "┴" });
            }
            s
        };
        vec![
            top(rows[0].len()),
            key_row(&rows[0]),
            between(0, rows[0].len()),
            format!(" {}", key_row(&rows[1])),
            between(1, rows[1].len()),
            format!("  {}", key_row(&rows[2])),
            bottom(2, rows[2].len()),
        ]
    }
}
