//! The practice companion shown with `--cat`.

use std::time::{Duration, Instant};

/// Width of the area the cat is drawn into.
pub const WIDTH: u16 = 17;
/// Height of the area the cat is drawn into.
pub const HEIGHT: u16 = 8;

const BODY: [&str; 5] = [
    "    /\\_/\\",
    "   >(•༝• )<",
    "    |    \\",
    "    || |  )",
    "    ll-l-//",
];

/// One position of the swinging tail: the paws in the ground line and the
/// two lines of tail below it.
struct Tail {
    paws: &'static str,
    upper: &'static str,
    lower: &'static str,
}

const TAILS: [Tail; 8] = [
    Tail { paws: "//", upper: "      <__/", lower: "" },
    Tail { paws: "||", upper: "        //", lower: "       <" },
    Tail { paws: "||", upper: "        //", lower: "        V" },
    Tail { paws: "||", upper: "         ||", lower: "         v" },
    Tail { paws: "||", upper: "         \\\\", lower: "          V" },
    Tail { paws: "||", upper: "          \\\\", lower: "           V" },
    Tail { paws: "||", upper: "          \\\\", lower: "            >" },
    Tail { paws: "\\\\", upper: "          \\__>", lower: "" },
];

/// The order in which the tail positions are shown.
const SWING: [usize; 15] = [4, 5, 6, 7, 7, 6, 4, 3, 2, 1, 0, 0, 1, 2, 3];

/// Time between two tail animation steps.
const STEP: Duration = Duration::from_millis(160);

pub struct Cat {
    frame: usize,
    last_step: Instant,
}

impl Cat {
    pub fn new() -> Self {
        Cat {
            frame: 0,
            last_step: Instant::now(),
        }
    }

    /// Advances the tail animation if enough time has passed.
    pub fn tick(&mut self) {
        if self.last_step.elapsed() >= STEP {
            self.frame = (self.frame + 1) % SWING.len();
            self.last_step = Instant::now();
        }
    }

    /// The lines of the current animation frame.
    pub fn lines(&self) -> Vec<String> {
        let tail = &TAILS[SWING[self.frame]];
        let mut lines: Vec<String> = BODY.iter().map(|s| s.to_string()).collect();
        lines.push(format!("/▔▔▔▔▔▔▔▔{}▔▔\\───", tail.paws));
        lines.push(tail.upper.to_string());
        lines.push(tail.lower.to_string());
        lines
    }
}
