    /// Advances the tail animation if enough time has passed.
    pub fn tick(&mut self) {
        if self.last_step.elapsed() >= STEP {
            self.frame = (self.frame + 1) % SWING.len();
            self.last_step = Instant::now();
        }
    }

    /// The lines of the current animation frame.
    pub fn lines(&self) -> Vec<String> {
        let tail = &TAILS[SWING[self.frame]];
        let mut lines: Vec<String> = BODY.iter().map(|s| s.to_string()).collect();
        lines.push(format!("/▔▔▔▔▔▔▔▔{}▔▔\\───", tail.paws));
        lines.push(tail.upper.to_string());
        lines.push(tail.lower.to_string());
        lines
    }
}
