        );
        stats_y = 14;
    }
    separator(frame, row(inner, stats_y));

    // statistics
    let gray = Style::default().fg(Color::Gray);
    let avg = game.average_result();
    let last = game.last_result();
    let stats = vec![
        Line::from(vec![
            Span::styled(format!("  need >= {:>3}WPM,   avg. ", game.need_wpm), gray),
            Span::raw(format!("{:>3}WPM", avg.wpm)),
            Span::styled(",   last", gray),
            Span::raw(format!(" {:>3}WPM", last.wpm)),
        ]),
        Line::from(vec![
            Span::styled(format!("  need >= {:>3}% Acc, avg. ", game.need_acc), gray),
            Span::raw(format!("{:>3}% Acc", avg.acc)),
            Span::styled(", last", gray),
            Span::raw(format!(" {:>3}% Acc", last.acc)),
        ]),
    ];
    frame.render_widget(
        Paragraph::new(stats),
        Rect::new(inner.x, inner.y + stats_y + 1, inner.width, 2),
    );

    // the companion
    if let Some(c) = view.cat {
        let area = Rect::new(
            window.right() - 1 - cat::WIDTH,
            10,
            cat::WIDTH,
            cat::HEIGHT,
        )
        .intersection(window);
        let lines: Vec<Line> = c.lines().into_iter().map(Line::from).collect();
        frame.render_widget(
            Paragraph::new(lines).style(Style::default().fg(Color::Reset)),
            area,
        );
    }

    // cursor at the next character to type (computed with wrapping arithmetic,
    // like the original window-centred calculation)
    let x = (window.width / 2)
        .wrapping_sub((game.text.len() / 2) as u16)
        .wrapping_add(game.typed.len() as u16);
    frame.set_cursor_position((window.x.wrapping_add(x), inner.y + 5));
}
