//! ngrrram - practice typing n-grams in the terminal.

mod cat;
mod game;
mod layout;
mod ngrams;
mod ui;

use std::io;
use std::process;
use std::time::Duration;

use clap::{value_parser, Arg, ArgAction, ArgMatches, Command};
use ratatui::backend::CrosstermBackend;
use ratatui::crossterm::event::{self, Event, KeyCode, KeyModifiers};
use ratatui::crossterm::execute;
use ratatui::crossterm::terminal::{
    disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen,
};
use ratatui::Terminal;

use crate::cat::Cat;
use crate::game::Game;
use crate::layout::{keyboard_lines, Emulator, KeyboardLayout};

/// Time to wait for input before redrawing.
const TICK: Duration = Duration::from_millis(16);

struct Options {
    n: String,
    top: i32,
    combi: i32,
    rep: i32,
    wpm: i32,
    acc: i32,
    emu_in: String,
    emu_out: String,
    show_ortho: bool,
    nokb: bool,
    cat: bool,
}

fn command() -> Command {
    Command::new("ngrrram")
        .arg(
            Arg::new("n")
                .short('n')
                .long("n")
                .value_name("2|3|4|w|file")
                .help("use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file.")
                .default_value("2"),
        )
        .arg(
            Arg::new("top")
                .short('t')
                .long("top")
                .value_name("1-200")
                .help("use the top X ngrams ordered by usage.")
                .value_parser(value_parser!(i32))
                .default_value("50"),
        )
        .arg(
            Arg::new("combi")
                .short('c')
                .long("combi")
                .value_name("1-200")
                .help("how many different ngrams to use in a single lesson.")
                .value_parser(value_parser!(i32))
                .default_value("2"),
        )
        .arg(
            Arg::new("rep")
                .short('r')
                .long("rep")
                .value_name("number")
                .help("how often to repeat *each* different ngram in a lesson.")
                .value_parser(value_parser!(i32))
                .default_value("3"),
        )
        .arg(
            Arg::new("wpm")
                .short('w')
                .long("wpm")
                .value_name("number")
                .help("the wpm threshold at which the lesson is considered a success.")
                .value_parser(value_parser!(i32))
                .default_value("40"),
        )
        .arg(
            Arg::new("acc")
                .short('a')
                .long("acc")
                .value_name("0-100")
                .help("the accuracy in percent at which the lesson is considered a success.")
                .value_parser(value_parser!(i32))
                .default_value("94"),
        )
        .arg(
            Arg::new("emu_in")
                .long("emu-in")
                .value_name("layout")
                .help("your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts.")
                .default_value(""),
        )
        .arg(
            Arg::new("emu_out")
                .long("emu-out")
                .value_name("layout")
                .help("the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts.")
                .default_value(""),
        )
        .arg(
            Arg::new("show_ortho")
                .long("show-ortho")
                .help("show keyboard in ortholinear format")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("nokb")
                .long("nokb")
                .help("pass this flag to disable the keyboard layout display.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("cat")
                .long("cat")
                .help("the most important flag. don't practice alone.")
                .action(ArgAction::SetTrue),
        )
}

fn options(m: &ArgMatches) -> Options {
    let s = |id: &str| m.get_one::<String>(id).cloned().unwrap_or_default();
    let i = |id: &str| m.get_one::<i32>(id).copied().unwrap_or_default();
    Options {
        n: s("n"),
        top: i("top"),
        combi: i("combi"),
        rep: i("rep"),
        wpm: i("wpm"),
        acc: i("acc"),
        emu_in: s("emu_in"),
        emu_out: s("emu_out"),
        show_ortho: m.get_flag("show_ortho"),
        nokb: m.get_flag("nokb"),
        cat: m.get_flag("cat"),
    }
}

fn fail(message: &str) -> ! {
    println!("{}", message);
    process::exit(1);
}

fn validate(o: &Options) {
    let ranges = [
        ("top", o.top, 1, 200),
        ("combi", o.combi, 1, 200),
        ("rep", o.rep, 1, 200),
        ("wpm", o.wpm, 1, 200),
        ("acc", o.acc, 0, 100),
    ];
    for (name, value, lo, hi) in ranges {
        if value < lo || value > hi {
            fail(&format!(
                "Invalid argument for {}. Use a number between {} and {}.",
                name, lo, hi
            ));
        }
    }
    if o.emu_in.is_empty() != o.emu_out.is_empty() {
        fail("You need to specify both emu_in and emu_out.");
    }
    if ngrams::builtin(&o.n).is_none() && !ngrams::file_exists(&o.n) {
        fail(&format!("File not found: {}", o.n));
    }
}

fn main() -> io::Result<()> {
    let opts = options(&command().get_matches());
    validate(&opts);

    let mut pool = ngrams::load(&opts.n);
    pool.truncate(opts.top as usize);

    let emulator = if opts.emu_in.is_empty() {
        None
    } else {
        Some(Emulator::new(
            KeyboardLayout::from_name(&opts.emu_in),
            KeyboardLayout::from_name(&opts.emu_out),
        ))
    };
    let display_layout = KeyboardLayout::from_name(&opts.emu_out);
    let keyboard = if opts.nokb {
        None
    } else {
        Some(keyboard_lines(&display_layout, opts.show_ortho))
    };

    let mut game = Game::new(
        pool,
        opts.combi as usize,
        opts.rep as usize,
        opts.wpm as u32,
        opts.acc as u32,
    );
    let mut cat = if opts.cat { Some(Cat::new()) } else { None };

    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    enable_raw_mode()?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;
    terminal.clear()?;

    let result = run(&mut terminal, &mut game, keyboard.as_deref(), &mut cat, emulator.as_ref());

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    result
}

fn run(
    terminal: &mut Terminal<CrosstermBackend<io::Stdout>>,
    game: &mut Game,
    keyboard: Option<&[String]>,
    cat: &mut Option<Cat>,
    emulator: Option<&Emulator>,
) -> io::Result<()> {
    loop {
        if let Some(c) = cat.as_mut() {
            c.tick();
        }
        terminal.draw(|frame| {
            let view = ui::View {
                game,
                keyboard,
                cat: cat.as_ref(),
            };
            ui::draw(frame, &view);
        })?;

        // the very first lesson is created right after the initial frame
        if game.lesson == 0 && game.is_complete() {
            game.next_lesson();
            continue;
        }

        if !event::poll(TICK)? {
            continue;
        }
        if let Event::Key(key) = event::read()? {
            match key.code {
                KeyCode::Esc => return Ok(()),
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    return Ok(())
                }
                KeyCode::Char(c) => {
                    let c = match emulator {
                        Some(e) => e.translate(c),
                        None => c,
                    };
                    game.type_char(c);
                }
                KeyCode::Enter => game.type_char(' '),
                KeyCode::Backspace => game.backspace(),
                _ => {}
            }
        }
    }
}
EOF
